{"fw_ld6_shelter_crim_1_0013","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"You snore, I'll put a sock in it",2,"Which sock?",1,"Yours, it's the one that's been in your boot for a week",2,"I'd rather be gagged by a dead rat",3,"That can be arranged"}},
{"fw_ld6_shelter_crim_1_0014","shelter",4,"reg=outlaw,raider,gang,club,crime,prison|mood=grim",{1,"Boss said keep moving",2,"Moving where?",1,"He didn't say where, just keep walking",3,"Then we're moving somewhere, shut up",2,"Somewhere's the one place we haven't been"}},
{"fw_ld6_shelter_crim_1_0015","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=sad",{1,"I used to have a pool",2,"A pool?",1,"In the backyard, above ground, with a ladder",2,"Why are you telling me this?",1,"I'd give my left nut to jump in it, ladder and all",3,"I'd drown you in it"}},
{"fw_ld6_shelter_crim_1_0016","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"Anybody got a better gun?",2,"That's a pretty good gun",1,"It jams every third shot",2,"Then shoot three at a time",3,"Shoot it at the guy who sold it to you"}},
{"fw_ld6_shelter_crim_1_0017","shelter",4,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"Where the fuck'd you get that watch?",2,"Found it",1,"You found it on a guy",2,"He didn't need it",1,"Is it set to the right time?",2,"I never know, no one does",3,"It's always Friday on that watch"}},
{"fw_ld6_shelter_crim_1_0018","shelter",4,"reg=outlaw,raider,gang,club,crime,prison|mood=fear",{1,"Somebody's talking to the Army",2,"Who?",1,"I don't know, but somebody knows where we are",3,"That's just you being a scared little bitch again",1,"I'm not scared, I'm paranoid, there's a fucking difference"}},
{"fw_ld6_shelter_crim_1_0019","shelter",2,"reg=outlaw,raider,gang,club,crime,prison|mood=angry",{1,"You're not the fuckin' boss of me",2,"I'm not trying to be",1,"You keep telling me what to do",2,"Because YOU keep fucking it up, you dumb shit!"}},
{"fw_ld6_shelter_crim_1_0020","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"Draw on his face while he sleeps",2,"With what?",1,"A burnt match",3,"Do it, I'll hold the light"}},
{"fw_ld6_shelter_crim_1_0021","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=warm",{1,"You're all right, you know that",2,"Don't get soft",1,"I'm not getting soft, quit looking at me",2,"Say it again and I'll cut your coffee",3,"What fuckin' coffee"}},
{"fw_ld6_shelter_crim_1_0022","shelter",2,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"I hate this heat",2,"Take your shirt off",1,"Not around you",2,"What's that supposed to mean?",1,"It means nobody wants to see that shit!"}},
{"fw_ld6_shelter_crim_1_0023","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"One time I stole a whole truck of Pepsi",2,"You did not",1,"A whole semi, drove it to Indiana, sold it in three days",2,"You smell like a Pepsi truck even now",3,"It's the cleanest he's ever been"}},
{"fw_ld6_shelter_crim_1_0024","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=sad",{1,"My granddaddy ran shine in Hart County",2,"Everybody's granddaddy ran shine",1,"Mine got caught once, did a year, said it was the best year of his life",2,"Why?",1,"No wife yelling at him, three meals a day",3,"That's every one of us right now"}},
{"fw_ld6_shelter_crim_1_0025","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=angry",{1,"Who the fuck ate my beans?!",2,"Wasn't me",1,"There was a whole can, and it's licked clean",3,"Look at your chin",1,"I didn't, I'm just saying look at your chin"}},
{"fw_ld6_shelter_crim_1_0026","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"I robbed a bank once with a spatula",2,"A spatula",1,"It was in my pocket, the guy didn't know it wasn't a gun",2,"How much",1,"Four hundred dollars and a free toaster",3,"Tell it right, the toaster was the whole point"}},
{"fw_ld6_shelter_crim_1_0027","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=angry",{1,"Bourbon's gone",2,"I know",1,"I'm drinking mouthwash",2,"We have mouthwash?",1,"We had mouthwash",3,"The mouthwash was mine"}},
{"fw_ld6_shelter_crim_1_0028","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"I'm the best shot here",2,"You couldn't hit a fuckin' barn!",1,"I hit the barn",2,"You hit the side of it, sideways, you fuckin' blind bat",3,"It's a big barn, it counts"}},
{"fw_ld6_shelter_crim_1_0029","shelter",3,"reg=outlaw,raider,gang,club,crime,prison|mood=angry|world=building",{1,"Fair share, that's all I want",2,"Fair according to who?",1,"According to me",2,"That's not how fair works",3,"It's how fair works in this room, I've got the gun"}},
{"fw_ld6_shelter_crim_1_0030","shelter",4,"reg=outlaw,raider,gang,club,crime,prison|mood=funny",{1,"You cry in your sleep",2,"I do not",1,"You called for your mama",2,"I called for my mama's pie, there's a difference",3,"There's no difference"}},
{"fw_ld6_shelter_crim_1_0031","shelter",2,"reg=outlaw,raider,gang,club,crime,prison|mood=sad",{1,"Look at 'em, all holed up in their little houses with their little curtains, the lucky bastards",2,"Don't",1,"I'm just looking, I never had a house",2,"Nobody here had a house"}},
{"fw_ld6_shelter_crim_1_0032","shelter",4,"reg=outlaw,raider,gang,club,crime,prison|mood=funny|world=door",{1,"New fish, you're on the door",2,"The door?",1,"Stand there and look scary, jackass",2,"I don't know how to look scary",3,"Think about your taxes"}},
{"fw_ld6_shelter_crim_1_0033","shelter",3,"reg=prison|mood=sad|world=building",{1,"I keep waiting for count",2,"What",1,"Count time, four o'clock, you stand by your bunk, and I'm standing by a couch",2,"Nobody's counting you",1,"I know, that's the thing, nobody's counting me",3,"I'll count you, one..."}},
{"fw_ld6_shelter_crim_1_0034","shelter",3,"reg=prison|mood=grim",{1,"I'm never going back",2,"Never's a long time",1,"I'd shoot myself first",2,"Don't say that",1,"It's a figure of speech..."}},
{"fw_ld6_shelter_crim_1_0035","shelter",4,"reg=prison|mood=funny",{1,"My cellie snored like a diesel truck at Eddyville",2,"At least he was reliable",1,"He was reliable at three in the morning",2,"That's what I'm saying",3,"My cellie sang, in the dark, off-key, every night"}},
{"fw_ld6_shelter_crim_1_0036","shelter",3,"reg=prison|mood=sad",{1,"I miss the yard",2,"The yard?",1,"A big flat field, with a fence, you could walk in a circle and think",2,"You can walk in a circle here",1,"It's not the same, there's no fence",3,"I'll build you a fence..."}},
{"fw_ld6_shelter_crim_1_0037","shelter",4,"reg=prison|mood=funny",{1,"Eight years for a car stereo",2,"It was a very nice stereo",1,"It was a Pioneer, I'd do it again",2,"You can't, there's no more cars",3,"Eight years, and you didn't even keep the stereo"}},
{"fw_ld6_shelter_crim_1_0038","shelter",4,"reg=prison|mood=funny",{1,"I never thought I'd miss a guard telling me to line up",2,"I miss the pudding",1,"The pudding was terrible",2,"A reliable kind of terrible",3,"I'd kill for a pudding"}},
{"fw_ld6_shelter_crim_1_0039","shelter",2,"reg=prison|mood=funny",{1,"Where'd you get that tattoo?",2,"On the yard, with a guitar string and some ink from a pen",1,"It looks like a squirrel",2,"It's an eagle"}},
{"fw_ld6_shelter_crim_1_0040","shelter",4,"reg=prison|mood=sad",{1,"Got a letter from my mother just before",2,"What'd it say?",1,"To eat my vegetables",2,"That's it?",1,"She wasn't a letter person",3,"Mine never wrote at all"}},
{"fw_ld6_shelter_crim_1_0041","shelter",3,"reg=prison|mood=funny",{1,"I had eleven days left on my sentence",2,"And you came out anyway...",1,"It was a very short walk",2,"Sometimes the door's just open",3,"You just walked out, I'm so jealous"}},
{"fw_ld6_shelter_crim_1_0042","shelter",4,"reg=prison|hour=4,11|mood=grim",{1,"They count us in the morning, the guards",2,"They counted us, you mean",1,"I counted myself in the mirror this morning, one",2,"It's the one number that doesn't change",3,"It changes, every day, I keep losing"}},
{"fw_ld6_shelter_crim_1_0043","shelter",4,"reg=prison|mood=funny",{1,"Anybody here ever been in the hole?",2,"Twice",3,"Once",4,"Three times, one was a clerical error",1,"That's about right"}},
{"fw_ld6_shelter_crim_1_0044","shelter",3,"reg=club|mood=sad",{1,"My bike's out of gas",2,"Mine's out of everything",1,"I keep sitting on it, just to feel it",3,"That's sad, man",1,"It's a good feeling, you wouldn't know"}},
{"fw_ld6_shelter_crim_1_0045","shelter",4,"reg=club|mood=funny",{1,"I miss telling a prospect to get me a beer",2,"Even when we didn't have any?",1,"Then I'd tell him to get me something wet",2,"And he'd offer water",1,"I'd call it an insult and ask for beer again",3,"I'd have brought you a bucket. Kept hoping you'd get the joke"}},
{"fw_ld6_shelter_crim_1_0046","shelter",3,"reg=club|mood=calm",{1,"You hear that?",2,"Pipes, way off",1,"That's a V-twin, I'd know it anywhere",2,"Whose?",1,"Nobody we know, whoever it is, he's got a nice sound",3,"Nice sound, wrong road"}},
{"fw_ld6_shelter_crim_1_0047","shelter",3,"reg=club|mood=sad",{1,"Polished that bike every Sunday for six years",2,"It's the cleanest bike in the county",1,"And now I can't get it started",2,"Maybe it just needs a little time",3,"Maybe it needs gas"}},
