{"fw_ld6_shelter_crim_1_0049","shelter",3,"reg=club|hour=4,9",{1,"Road captain says we move at dawn",2,"Which way?",1,"He didn't say, he said dawn",2,"That's all you get from him, dawn",3,"Dawn's good enough"}},
{"fw_ld6_shelter_crim_1_0050","shelter",3,"reg=club|mood=angry",{1,"I earned that patch",2,"I know you did",1,"I earned it with a broken wrist and a ticket in three states",2,"Nobody's taking your patch",3,"Anybody tries, we'll have a conversation"}},
{"fw_ld6_shelter_crim_1_0051","shelter",4,"reg=club|mood=funny|world=inside",{1,"Anybody got a bandana?",2,"What for?",1,"My nose, the smell in here",3,"It's your smell",4,"It's his smell and mine and everybody's, take it up with God"}},
{"fw_ld6_shelter_crim_1_0052","shelter",2,"reg=club|mood=sad",{1,"Used to be nothing like a Sunday run, forty bikes and the road open",2,"Quit it",1,"I'm just saying, I can still hear it"}},
{"fw_ld6_shelter_crim_1_0053","shelter",4,"reg=gang,crime|mood=angry",{1,"Boss said we hold this block",2,"There's no block, there's a house",1,"Then we hold the house",2,"It's not ours",1,"It's ours now, I don't care",3,"It's got a roof, it's ours"}},
