{"fw_ld6_shelter_crim_1_0055","shelter",3,"reg=gang,crime|mood=angry",{1,"The old man's gonna want his cut",2,"There's no cut, there's no old man",1,"He's alive, I know it",2,"Then he's running late, and when he arrives he'll want his cut",1,"Yeah",3,"Then we'd better have a cut"}},
{"fw_ld6_shelter_crim_1_0056","shelter",3,"reg=gang,crime|mood=funny",{1,"I do business with anybody",2,"There's nobody left to do business with",1,"There's always somebody, there's a guy down the road with six chickens",2,"What do we have to trade?",1,"A story about chickens",3,"I'd buy a chicken story"}},
{"fw_ld6_shelter_crim_1_0057","shelter",2,"reg=gang,crime|mood=funny",{1,"Funny how nobody calls the cops now",2,"I miss that, I miss being a little bit worried",1,"You were never worried",2,"I was worried about my mother, finding out"}},
{"fw_ld6_shelter_crim_1_0058","shelter",3,"reg=gang,crime|hour=16,5|mood=sad",{1,"This crew isn't my family",2,"It's all you've got",1,"It's all I've got, that's what I'm saying, it's not enough",3,"It's enough for tonight..."}},
{"fw_ld6_shelter_crim_1_0059","shelter",3,"reg=gang,crime|mood=funny",{1,"I ran booze into dry counties for six years",2,"Which ones?",1,"Hardin was dry, you could drive a truck of Beam through at three in the morning and the sheriff waved",3,"The sheriff was in the truck"}},
{"fw_ld6_shelter_crim_1_0060","shelter",4,"reg=gang,crime|mood=angry",{1,"You owe me a favor",2,"I-- I don't owe you a damn thing",1,"You owe me one for the thing at the quarry",2,"That's a favor from two years ago",3,"Favors don't expire, ask my cousin"}},
