{"fw_ld6_shelter_lawmil_1_0004","shelter",3,"reg=law,swat|day=1,13|mood=sad",{1,"I was supposed to be off Friday, I was supposed to be at a fuckin' ballgame",2,"Everybody was supposed to be off Friday",1,"I traded shifts for a ballgame",2,"Did you go",1,"Never made it, got called in at four",3,"Reds game?"}},
