{"fw_ld6_shelter_lawmil_1_0006","shelter",4,"reg=law,swat|day=2,13",{1,"Sheriff said hold at the substation",2,"Sheriff stopped answering Saturday",1,"So who's giving the orders now?",3,"Nobody, so we hold",4,"Hold what, exactly"}},
{"fw_ld6_shelter_lawmil_1_0007","shelter",3,"reg=law,swat|mood=sad",{1,"I was gonna put in my papers in September",2,"Retire?",1,"Thirty-one years in September",2,"Thirty-one, damn",1,"Yeah, I was gonna buy a boat",3,"A boat, where, Nolin Lake?"}},
