{"fw_ld6_shelter_lawmil_1_0009","shelter",2,"reg=law,swat|mood=sad",{1,"I've got keys to thirty cells and nobody to put in them",2,"Keep the keys",1,"I keep checking my belt for them, like I'll forget how to open a door"}},
{"fw_ld6_shelter_lawmil_1_0010","shelter",4,"reg=law,swat|mood=grim",{1,"I count everybody every hour, it's a habit",2,"Eleven years at the jail?",1,"Eleven years, you count heads at four in the morning in your sleep",2,"How many are we",1,"Five, right now, five and one asleep, so six",3,"Five and one asleep, that's six, quit saying it"}},
